-- Guest Hub S2e (26 Nov 2026 — Ahmed's approved comment sections of 21 Nov 2026, SOCIAL-SPEC.md §11; DECISIONS.md 2026-11-26
-- «Guest Hub S2e»). Generated by scripts/hub-s2e-migration.mjs — never edited once applied (CLAUDE.md §12). No unit mode,
-- licence or switch changes: the comment switches stay OFF (the system admin's). Every UPDATE / DELETE carries a WHERE.

-- ── 1. Ahmed's approved public texts (his spec §8, 21 Nov 2026), word for word ──
create or replace function internal.hub_comment_texts_problems(t jsonb) returns text[]
language plpgsql immutable set search_path = '' as $$
declare
  v text[] := '{}';
  c text;
  l text;
  x text;
  i integer;
begin
  if t is null or jsonb_typeof(t) <> 'object' then return array['missing']; end if;
  foreach c in array array['question', 'price', 'complaint', 'praise'] loop
    foreach l in array array['ar', 'en'] loop
      if jsonb_typeof(t #> array['public', c, l]) <> 'array' or jsonb_array_length(t #> array['public', c, l]) = 0 then
        v := v || ('public.' || c || '.' || l);
      else
        i := 0;
        for x in select jsonb_array_elements_text(t #> array['public', c, l]) loop
          if coalesce(btrim(x), '') = '' then v := v || ('public.' || c || '.' || l || '.' || i || ':empty');
          elsif x ~ '[0-9٠-٩۰-۹]' then v := v || ('public.' || c || '.' || l || '.' || i || ':digit');
          elsif x ~* '(ريال|ر\.س|﷼|درهم|دولار|\msar\M|\msr\M|\musd\M|\$|€|£|%|٪|يبدأ من|ابتداءً من|ابتداء من|\mstarting (at|from)\M)' then v := v || ('public.' || c || '.' || l || '.' || i || ':price');
          elsif char_length(x) > 300 then v := v || ('public.' || c || '.' || l || '.' || i || ':long');
          elsif x ~* '(https?://|www\.)' then v := v || ('public.' || c || '.' || l || '.' || i || ':link');
          end if;
          i := i + 1;
        end loop;
      end if;
    end loop;
  end loop;
  -- S2e: no fixed private text (SOCIAL-SPEC §5.3 — the assistant's answer, the complaint hand-off notice)
  return v;
end;
$$;
comment on table public.hub_comment_texts is 'S2: Ahmed''s approved public comment texts (his spec §8, 21 Nov 2026 — SOCIAL-SPEC.md §11): {public: {question|price|complaint|praise: {ar: [variants], en: [variants]}}}. Written only by a migration, word for word. The private message is the assistant''s answer (S2e).';
update public.hub_comment_texts
   set texts = $s2e${"public":{"question":{"ar":["أهلًا بك، أرسلنا لك التفاصيل في رسالة خاصة.","يسعدنا سؤالك، تجد التفاصيل في رسائلك الخاصة.","تم الرد عليك في الخاص، ويسعدنا خدمتك."],"en":["Welcome! We've sent you the details in a private message.","Thanks for asking. You'll find the details in your messages.","We've replied to you privately. Happy to help."]},"price":{"ar":["الأسعار حسب تاريخ الإقامة، أرسلنا لك رسالة خاصة لنعرف تواريخك.","يعتمد السعر على تواريخ إقامتك، تابع رسائلك الخاصة."],"en":["Prices depend on your dates. We've sent you a private message to ask for them.","The price depends on your stay dates. Please check your messages."]},"complaint":{"ar":["نأسف لما واجهته، تواصلنا معك في الخاص لمتابعة الأمر.","نعتذر منك، أرسلنا لك رسالة خاصة ليتابع الفريق طلبك."],"en":["We're sorry about your experience. We've contacted you privately to follow up.","We apologise. We've sent you a private message so our team can follow up."]},"praise":{"ar":["شكرًا لك على كلماتك الجميلة.","شكرًا لك، يسعدنا ذلك كثيرًا.","سعداء برأيك، شكرًا لك."],"en":["Thank you for your kind words.","Thank you, that means a lot to us.","We're glad to hear it. Thank you."]}}}$s2e$::jsonb, version = '2026-11-21', approved_by = 'Ahmed, 21 Nov 2026', set_at = now()
 where id = 1;
do $$
begin
  if cardinality(internal.hub_comment_texts_problems((select t.texts from public.hub_comment_texts t where t.id = 1))) > 0 then
    raise exception 's2e: the approved texts do not pass their own check';
  end if;
end $$;

-- ── 2. the audience per channel (Ahmed's §6: «Settings per channel: test / live / standby») — NULL = the unit's ──
alter table public.hub_channels add column if not exists social_mode text;
alter table public.hub_channels drop constraint if exists hub_channels_social_mode;
alter table public.hub_channels add constraint hub_channels_social_mode check (social_mode is null or (social_mode in ('test', 'live', 'standby') and provider = 'meta'));
comment on column public.hub_channels.social_mode is 'S2e: a Meta channel''s own audience (test «حسابات التجربة فقط» · live «الكل» · standby «الكل مع وضع الاستعداد»); NULL = its unit''s social_mode.';
create or replace function internal.hub_channel_audience(p_channel uuid) returns text
language sql stable security definer set search_path = '' as $$
  select coalesce(ch.social_mode, u.social_mode) from public.hub_channels ch join public.hub_units u on u.id = ch.unit_id where ch.id = p_channel
$$;
create or replace function public.hub_channel_audience_set(p_channel uuid, p_mode text) returns jsonb
language plpgsql security definer set search_path = '' as $$
declare
  ch public.hub_channels;
  v_batch uuid;
begin
  if not internal.is_system_admin() then raise exception 'hub_system_admin_only' using errcode = '42501'; end if;
  select * into ch from public.hub_channels where id = p_channel for update;
  if ch.id is null or ch.provider <> 'meta' then raise exception 'not_found' using errcode = '22023'; end if;
  if p_mode is not null and p_mode not in ('test', 'live', 'standby') then raise exception 'invalid' using errcode = '22023'; end if;
  if ch.social_mode is not distinct from p_mode then raise exception 'nothing to change' using errcode = '22023'; end if;
  v_batch := internal.begin_batch();
  update public.hub_channels set social_mode = p_mode where id = ch.id;
  -- the channels' audit trigger names its columns (not this one): the change is written here, one row of the batch
  insert into public.audit_log (actor_id, actor_label, entity, entity_id, branch, action, old, new, batch_id)
  values (auth.uid(), coalesce((select st.full_name from public.staff st where st.user_id = auth.uid()), 'system'), 'hub_channels', ch.id::text, null, 'update',
          jsonb_build_object('social_mode', ch.social_mode), jsonb_build_object('social_mode', p_mode), v_batch);
  return jsonb_build_object('ok', true, 'batch_id', v_batch, 'before', ch.social_mode);
end;
$$;
revoke execute on function public.hub_channel_audience_set(uuid, text) from public, anon;
grant execute on function public.hub_channel_audience_set(uuid, text) to authenticated, service_role;
revoke execute on function internal.hub_channel_audience(uuid) from public, anon, authenticated;

create or replace function internal.hub_social_may_reply(c public.hub_conversations) returns boolean
language sql stable security definer set search_path = '' as $$
  select case
    when ch.provider <> 'meta' then true
    -- S2e: the channel's own audience, else its unit's
    when coalesce(ch.social_mode, cu.social_mode) in ('live', 'standby') then true
    else coalesce((select i.tester from public.hub_social_identities i where i.channel_id = c.channel_id and i.guest_profile_id = c.guest_profile_id and i.is_test = c.is_test limit 1), false)
  end
    from public.hub_channels ch join public.hub_units cu on cu.id = ch.unit_id
   where ch.id = c.channel_id
$$;

create or replace function internal.hub_standby_reason(p_conversation uuid, p_message uuid, p_kind text, p_at timestamptz default now()) returns text
language sql stable security definer set search_path = '' as $$
  select case
    when p_kind <> 'reply' then 'tag'
    when exists (select 1 from public.hub_messages m where m.id = p_message and (m.kind in ('interactive', 'button_reply') or m.payload ? 'button_id')) then 'tap'
    -- S2e: the conversation's channel's own audience, else the unit's
    when u.kind = 'brand' and coalesce(internal.hub_channel_audience(c.channel_id), u.social_mode) <> 'standby' then 'off'
    when u.kind <> 'brand' and (not coalesce(t.standby_on, false) or coalesce(t.standby_minutes, 0) not between 1 and 30) then 'off'
    when internal.hub_assistant_engaged(p_conversation) and internal.hub_exchange_open(p_conversation, p_message, p_at) then 'engaged'
    when not exists (select 1 from public.hub_staff_slots s where s.active and internal.hub_slot_covers(s, p_at)
                       and (s.branch_slug = u.branch_slug or (u.kind = 'brand' and (c.branch_slug is null or s.branch_slug = c.branch_slug)))) then 'no_shift'
    else 'waiting' end
    from public.hub_conversations c join public.hub_units u on u.id = c.unit_id left join public.hub_team_branches t on t.branch_slug = u.branch_slug
   where c.id = p_conversation
$$;

create or replace function public.hub_social_overview() returns jsonb
language plpgsql stable security definer set search_path = '' as $$
declare u public.hub_units;
begin
  if not (internal.can('assistant', 'view') and internal.can_branch(null)) then raise exception 'hub_forbidden' using errcode = '42501'; end if;
  select * into u from public.hub_units where key = 'social';
  if u.id is null then return jsonb_build_object('unit', null); end if;
  return jsonb_build_object(
    'unit', jsonb_build_object('id', u.id, 'key', u.key, 'name_ar', u.name_ar, 'mode', u.assistant_mode, 'social_mode', u.social_mode,
                               'standby_minutes', u.social_standby_minutes, 'human_agent', u.meta_human_agent, 'status', u.status),
    'channels', (select coalesce(jsonb_agg(jsonb_build_object('id', c.id, 'kind', c.kind, 'address', c.address, 'display_name', c.display_name, 'connected', c.connected,
                                                         'verified_at', c.verified_at, 'sending_enabled', c.sending_enabled,
                                                         'social_mode', c.social_mode, 'audience', coalesce(c.social_mode, u.social_mode)) order by c.kind), '[]'::jsonb)
                   from public.hub_channels c where c.unit_id = u.id),
    'accounts', (select coalesce(jsonb_agg(jsonb_build_object('id', i.id, 'kind', i.kind, 'name', i.display_name, 'username', i.username, 'tester', i.tester,
                                                         'last_seen_at', i.last_seen_at, 'tester_set_at', i.tester_set_at) order by i.tester desc, i.last_seen_at desc), '[]'::jsonb)
                   from (select * from public.hub_social_identities x where not x.is_test order by x.tester desc, x.last_seen_at desc limit 30) i),
    'system_admin', internal.is_system_admin());
end;
$$;

create or replace function public.hub_comment_ingest(p jsonb) returns jsonb
language plpgsql security definer set search_path = '' as $$
declare
  ch public.hub_channels;
  u public.hub_units;
  v_kind text := p ->> 'kind';
  v_skip text := nullif(p ->> 'skip', '');
  v_id uuid;
  v_tester boolean;
  v_parent public.hub_comments;
  v_state text := 'new';
  v_test boolean := coalesce((p ->> 'is_test')::boolean, false);
begin
  if v_kind not in ('instagram', 'facebook') then return jsonb_build_object('stored', false, 'reason', 'kind'); end if;
  select * into ch from public.hub_channels x
   where x.provider = 'meta' and x.kind = case when v_kind = 'instagram' then 'instagram' else 'messenger' end and x.address = p ->> 'channel';
  if ch.id is null then return jsonb_build_object('stored', false, 'reason', 'unknown_channel'); end if;
  select * into u from public.hub_units where id = ch.unit_id;
  -- our own comment: one of our public replies (its id, or its text while the id is not recorded yet) — or a staff member's
  -- reply from the Instagram / Facebook app, which ends that thread for the assistant
  if v_skip = 'own' and nullif(p ->> 'parent_id', '') is not null then
    select * into v_parent from public.hub_comments x where x.channel_id = ch.id and x.comment_id = p ->> 'parent_id';
    if v_parent.id is not null and not (v_parent.public_id is not distinct from (p ->> 'comment_id')
         or (v_parent.public_id is null and btrim(coalesce(v_parent.public_body, '')) = btrim(coalesce(p ->> 'body', '')))) then
      update public.hub_comments set staff_answered_at = coalesce(staff_answered_at, now()) where id = v_parent.id;
    end if;
  end if;
  v_tester := exists (select 1 from public.hub_social_identities i
                       where i.channel_id = ch.id and i.tester and (i.user_id = p ->> 'author_id' or (v_kind = 'instagram' and lower(i.username) = lower(p ->> 'author_name'))))
           or exists (select 1 from public.hub_comment_testers t where t.channel_id = ch.id and t.author_id = p ->> 'author_id');
  -- S2e (SOCIAL-SPEC §5.1): a reply inside a thread a staff member already answered is ignored
  if v_skip is null and nullif(p ->> 'parent_id', '') is not null
     and exists (select 1 from public.hub_comments x where x.channel_id = ch.id and x.comment_id = p ->> 'parent_id' and x.staff_answered_at is not null) then
    v_skip := 'staff_thread';
  end if;
  if v_skip is null then
    if not ch.comments_on then v_skip := 'switch_off';
    elsif u.assistant_mode = 'off' then v_skip := 'unit_off';
    elsif coalesce(ch.social_mode, u.social_mode) = 'test' and not v_tester then v_skip := 'not_tester';
    end if;
  end if;
  if v_skip is not null then v_state := 'skipped'; end if;
  insert into public.hub_comments (channel_id, kind, comment_id, parent_id, post_id, is_ad, author_id, author_name, body, commented_at, state, skip_reason, tester, is_test)
  values (ch.id, v_kind, p ->> 'comment_id', nullif(p ->> 'parent_id', ''), nullif(p ->> 'post_id', ''), coalesce((p ->> 'ad')::boolean, false),
          nullif(p ->> 'author_id', ''), left(nullif(p ->> 'author_name', ''), 120), left(nullif(p ->> 'body', ''), 2000),
          coalesce((p ->> 'commented_at')::timestamptz, now()), v_state, v_skip, v_tester, v_test)
  on conflict (channel_id, comment_id) do nothing
  returning id into v_id;
  if v_id is null then return jsonb_build_object('stored', false, 'reason', 'duplicate'); end if;
  return jsonb_build_object('stored', true, 'id', v_id, 'process', v_state = 'new', 'skip', v_skip, 'tester', v_tester);
end;
$$;

create or replace function public.hub_comment_claim(p_id uuid) returns jsonb
language plpgsql security definer set search_path = '' as $$
declare
  c public.hub_comments;
  ch public.hub_channels;
  u public.hub_units;
  v_thread_staff boolean;
begin
  select * into c from public.hub_comments where id = p_id for update skip locked;
  if c.id is null then return jsonb_build_object('claimed', false, 'reason', 'busy'); end if;
  if not (c.state = 'new' or (c.state = 'processing' and c.claimed_at < now() - interval '3 minutes' and c.attempts < 3)) then
    return jsonb_build_object('claimed', false, 'reason', c.state);
  end if;
  select * into ch from public.hub_channels where id = c.channel_id;
  select * into u from public.hub_units where id = ch.unit_id;
  -- the switches and the audience again (they may have changed since the comment arrived); a thread a staff member answered
  -- S2e: the channel's own audience; a thread a staff member answered (the comment's own, or its parent's)
  v_thread_staff := c.parent_id is not null and exists (select 1 from public.hub_comments x where x.channel_id = c.channel_id and x.comment_id = c.parent_id and x.staff_answered_at is not null);
  if not ch.comments_on or u.assistant_mode = 'off' or (coalesce(ch.social_mode, u.social_mode) = 'test' and not c.tester) or c.staff_answered_at is not null or v_thread_staff then
    update public.hub_comments set state = 'skipped', done_at = now(),
           skip_reason = case when not ch.comments_on then 'switch_off' when u.assistant_mode = 'off' then 'unit_off' when c.staff_answered_at is not null then 'staff_answered'
                              when v_thread_staff then 'staff_thread' else 'not_tester' end
     where id = c.id;
    return jsonb_build_object('claimed', false, 'reason', 'skipped');
  end if;
  update public.hub_comments set state = 'processing', claimed_at = now(), attempts = attempts + 1 where id = c.id;
  return jsonb_build_object('claimed', true,
    'comment', jsonb_build_object('id', c.id, 'kind', c.kind, 'comment_id', c.comment_id, 'post_id', c.post_id, 'is_ad', c.is_ad, 'body', c.body,
                                  'commented_at', c.commented_at, 'has_post', c.post_permalink is not null or c.post_thumb is not null, 'is_test', c.is_test,
                                  -- S2e: a reply inside a thread; under our own public reply (never a public reply to our own reply)
                                  'in_thread', c.parent_id is not null,
                                  'thread_ours', c.parent_id is not null and exists (select 1 from public.hub_comments x where x.channel_id = c.channel_id
                                                   and x.comment_id = c.parent_id and x.public_status = 'sent')),
    'channel', jsonb_build_object('id', ch.id, 'kind', ch.kind, 'address', ch.address, 'page_id', coalesce(ch.page_id, ch.address), 'private_on', ch.comment_private_on),
    'unit', jsonb_build_object('id', u.id, 'key', u.key, 'mode', u.assistant_mode),
    'budget', internal.hub_budget_state(),
    'texts', (select t.texts from public.hub_comment_texts t where t.id = 1),
    'used', coalesce((select jsonb_object_agg(x.class || ':' || x.language, x.n) from (
               select y.class, y.language, count(*) n from public.hub_comments y
                where y.channel_id = c.channel_id and y.public_status = 'sent' and y.class is not null and y.language is not null group by y.class, y.language) x), '{}'::jsonb),
    'models', (select s.value from public.settings s where s.key = 'hub_models'),
    'prices', (select s.value from public.settings s where s.key = 'hub_model_prices'));
end;
$$;

create or replace function public.hub_comment_done(p_id uuid, p jsonb) returns jsonb
language plpgsql security definer set search_path = '' as $$
declare
  c public.hub_comments;
  ch public.hub_channels;
  v_state text := p ->> 'state';
  v_handoff uuid;
  m jsonb;
  v_question boolean := (p ->> 'handoff_reason') = 'comment_question';
begin
  select * into c from public.hub_comments where id = p_id for update;
  if c.id is null then raise exception 'not_found' using errcode = '22023'; end if;
  select * into ch from public.hub_channels where id = c.channel_id;
  if v_state not in ('replied', 'handed_off', 'skipped', 'review', 'test', 'failed') then raise exception 'hub_comment_state' using errcode = '22023'; end if;
  update public.hub_comments set
    class = coalesce(p ->> 'class', class), language = coalesce(p ->> 'language', language), state = v_state,
    skip_reason = nullif(p ->> 'reason', ''), classified_at = coalesce(classified_at, case when p ? 'class' then now() end), done_at = now(),
    public_body = coalesce(left(p ->> 'public_body', 1000), public_body), public_variant = coalesce((p ->> 'public_variant')::integer, public_variant),
    public_id = coalesce(nullif(p ->> 'public_id', ''), public_id), public_status = coalesce(nullif(p ->> 'public_status', ''), public_status),
    public_error = coalesce(nullif(p ->> 'public_error', ''), public_error), public_at = case when p ? 'public_status' then now() else public_at end,
    private_body = coalesce(left(p ->> 'private_body', 1000), private_body), private_status = coalesce(nullif(p ->> 'private_status', ''), private_status),
    private_error = coalesce(nullif(p ->> 'private_error', ''), private_error), private_at = case when p ? 'private_status' then now() else private_at end,
    conversation_id = coalesce(nullif(p ->> 'conversation_id', '')::uuid, conversation_id),
    post_permalink = coalesce(nullif(p ->> 'post_permalink', ''), post_permalink), post_thumb = coalesce(nullif(p ->> 'post_thumb', ''), post_thumb),
    post_product = coalesce(nullif(p ->> 'post_product', ''), post_product)
   where id = c.id;
  -- the classifier's cost, on «السوشيال» (layer tag)
  if (p ->> 'input_tokens') is not null then
    perform internal.hub_usage_add(ch.unit_id, 'tag', 'turn', coalesce(p ->> 'model', 'claude-sonnet-5-5'), (p ->> 'input_tokens')::bigint, coalesce((p ->> 'output_tokens')::bigint, 0), c.is_test);
  end if;
  -- S2e: the private answer's model calls (the engine on «السوشيال»)
  for m in select * from jsonb_array_elements(case when jsonb_typeof(p -> 'models') = 'array' then p -> 'models' else '[]'::jsonb end) loop
    if coalesce((m ->> 'input_tokens')::bigint, 0) + coalesce((m ->> 'output_tokens')::bigint, 0) > 0 then
      perform internal.hub_usage_add(ch.unit_id, case when m ->> 'layer' in ('understand', 'compose', 'tag', 'vision', 'summary') then m ->> 'layer' else 'understand' end, 'turn',
                                     coalesce(m ->> 'model', 'claude-sonnet-5-5'), coalesce((m ->> 'input_tokens')::bigint, 0), coalesce((m ->> 'output_tokens')::bigint, 0), c.is_test);
    end if;
  end loop;
  -- a complaint: the comment's hand-off — both branches (a test account's: the system admin only, S1c)
  if v_state = 'handed_off' and c.handoff_id is null then
    v_handoff := gen_random_uuid();
    insert into public.hub_handoffs (id, conversation_id, comment_id, unit_id, branch_slug, reason, summary, ref_text, is_test, both_branches)
    values (v_handoff, null, c.id, ch.unit_id, 'airport-road', case when v_question then 'comment_question' else 'comment_complaint' end,
            case when v_question then (case when c.kind = 'instagram' then 'سؤال في تعليق على انستجرام يحتاج الفريق' else 'سؤال في تعليق على فيسبوك يحتاج الفريق' end)
                 when c.kind = 'instagram' then 'شكوى في تعليق على انستجرام' else 'شكوى في تعليق على فيسبوك' end, 'تعليق', c.is_test, not c.tester);
    update public.hub_comments set handoff_id = v_handoff where id = c.id;
    perform internal.hub_handoff_queue(v_handoff, 'alert');
  end if;
  return jsonb_build_object('ok', true, 'handoff_id', v_handoff);
end;
$$;

create or replace function public.report_hub(p_branch text, p_from date, p_to date) returns jsonb
language plpgsql stable security definer set search_path = '' as $$
declare
  v_br text[] := internal.metrics_branches('reports', p_branch);
  v_a timestamptz;
  v_b timestamptz;
  v_rate numeric := coalesce((internal.setting('wa_message_cost') ->> 'utility')::numeric, 0);
  v_out jsonb;
begin
  perform internal.metrics_period(p_from, p_to);
  v_a := p_from::timestamp at time zone 'Asia/Riyadh';
  v_b := (p_to + 1)::timestamp at time zone 'Asia/Riyadh';
  with units as (
    select u.id, u.key, u.name_ar, u.branch_slug, u.sort from public.hub_units u where u.branch_slug = any (v_br) and not u.is_test),
  conv as (
    select c.* from public.hub_conversations c where not c.is_test and c.created_at >= v_a and c.created_at < v_b and c.unit_id in (select id from units)),
  -- the assistant's first reply: the episode's first live reply turn that answered (from the episode's first guest message —
  -- the conversation's start); the turns, never the message table (no text is read by a report)
  first_ai as (
    select t.conversation_id, min(t.finished_at) as at from public.hub_turns t join conv c on c.id = t.conversation_id
     where t.kind = 'reply' and t.status = 'done' and t.mode = 'live' and not t.is_test
       and exists (select 1 from jsonb_array_elements_text(coalesce(t.decision -> 'actions', '[]'::jsonb)) a where a not in ('noop', 'tag', 'handoff')) group by 1),
  ai_rt as (
    select c.unit_id, extract(epoch from a.at - c.created_at) / 60.0 as min from conv c join first_ai a on a.conversation_id = c.id where a.at >= c.created_at),
  ho as (
    select h.* from public.hub_handoffs h where not h.is_test and not h.extra and h.created_at >= v_a and h.created_at < v_b and h.unit_id in (select id from units)),
  staff_rt as (select h.unit_id, extract(epoch from h.first_reply_at - h.created_at) / 60.0 as min from ho h where h.first_reply_at is not null),
  drafts as (
    select d.*, c.unit_id from public.hub_drafts d join conv c on c.id = d.conversation_id where d.kind = 'stay' and not d.sim and not d.is_test),
  bk as (
    select r.* from public.reservations r where not r.is_test and r.booking_source = 'assistant_whatsapp' and r.created_at >= v_a and r.created_at < v_b and r.branch = any (v_br)),
  topics as (
    select k, count(*) as n from public.hub_turns t cross join lateral unnest(t.topics) k
     where not t.is_test and t.kind = 'reply' and t.created_at >= v_a and t.created_at < v_b and t.unit_id in (select id from units)
       and k not in ('greeting', 'thanks_closing') group by k order by n desc, k limit 10)
  select jsonb_build_object(
    'period', jsonb_build_object('from', p_from, 'to', p_to),
    'units', (select coalesce(jsonb_agg(jsonb_build_object(
        'key', un.key, 'name_ar', un.name_ar, 'branch', un.branch_slug,
        'conversations', (select count(*) from conv c where c.unit_id = un.id),
        'handed_off', (select count(distinct h.conversation_id) from ho h where h.unit_id = un.id),
        'assistant_only', (select count(*) from conv c where c.unit_id = un.id and exists (select 1 from first_ai a where a.conversation_id = c.id)
                            and not exists (select 1 from ho h where h.conversation_id = c.id)),
        'ai_median_min', (select round(percentile_cont(0.5) within group (order by x.min)::numeric, 1) from ai_rt x where x.unit_id = un.id),
        'ai_p90_min', (select round(percentile_cont(0.9) within group (order by x.min)::numeric, 1) from ai_rt x where x.unit_id = un.id),
        'staff_median_min', (select round(percentile_cont(0.5) within group (order by x.min)::numeric, 1) from staff_rt x where x.unit_id = un.id),
        'staff_p90_min', (select round(percentile_cont(0.9) within group (order by x.min)::numeric, 1) from staff_rt x where x.unit_id = un.id),
        'quoted', (select count(*) from drafts d where d.unit_id = un.id and d.quote is not null),
        'booked', (select count(*) from drafts d where d.unit_id = un.id and d.reservation_id is not null),
        -- «وضع الاستعداد»: the waits answered by staff inside them / by the assistant after them
        'standby_staff', (select count(*) from public.hub_turns t where t.unit_id = un.id and not t.is_test and t.standby_outcome = 'staff'
                           and t.created_at >= v_a and t.created_at < v_b),
        'standby_assistant', (select count(*) from public.hub_turns t where t.unit_id = un.id and not t.is_test and t.standby_outcome = 'assistant'
                               and t.created_at >= v_a and t.created_at < v_b),
        'model_cost_usd', (select round(coalesce(sum(x.cost_usd), 0), 4) from public.hub_usage_daily x
                            where x.unit_id = un.id and not x.is_test and x.source in ('turn', 'staff') and x.day between p_from and p_to))
        order by un.sort, un.key), '[]'::jsonb) from units un),
    'bookings', (select jsonb_build_object('instant', count(*) filter (where b.confirmation = 'instant'), 'request', count(*) filter (where b.confirmation is distinct from 'instant'),
                                           'confirmed', count(*) filter (where b.status = 'confirmed'),
                                           'revenue', coalesce(sum(internal.res_revenue(b.id)) filter (where b.status = 'confirmed'), 0)) from bk b),
    'sales_requests', (select jsonb_build_object('hall', count(*) filter (where e.request_type = 'event'), 'group', count(*) filter (where e.request_type <> 'event'))
                         from public.partner_enquiries e where not e.is_test and e.page_url = 'whatsapp' and e.created_at >= v_a and e.created_at < v_b
                           and (e.branch = any (v_br) or e.branch = 'both')),
    'topics', (select coalesce(jsonb_agg(jsonb_build_object('key', t.k, 'label_ar', coalesce(x.label_ar, t.k), 'count', t.n) order by t.n desc, t.k), '[]'::jsonb)
                 from topics t left join public.hub_topics x on x.key = t.k),
    -- S2e (Ahmed's §6): the conversations per channel (WhatsApp, Instagram, Messenger); «السوشيال» counted by its
    -- conversation's branch, or — branch unknown — for a user who sees every branch
    'by_channel', (select jsonb_build_object('whatsapp', count(*) filter (where ch.kind not in ('instagram', 'messenger')),
                                             'instagram', count(*) filter (where ch.kind = 'instagram'), 'messenger', count(*) filter (where ch.kind = 'messenger'))
                     from public.hub_conversations c join public.hub_channels ch on ch.id = c.channel_id join public.hub_units u on u.id = c.unit_id
                    where not c.is_test and c.created_at >= v_a and c.created_at < v_b and not u.is_test
                      and (u.branch_slug = any (v_br) or (u.branch_slug is null and (c.branch_slug = any (v_br) or (c.branch_slug is null and cardinality(v_br) >= 2))))),
    'whatsapp', (select jsonb_build_object('templates', n, 'estimate_usd', round(n * v_rate, 4)) from (
        select (select count(*) from public.hub_staff_sends s where not s.is_test and s.status in ('accepted', 'sent', 'delivered', 'read') and s.created_at >= v_a and s.created_at < v_b)
             + (select count(*) from public.whatsapp_messages w join bk b on b.ref = w.ref where w.status in ('accepted', 'sent', 'delivered', 'read')) as n) z))
  into v_out;
  return internal.money(v_out);
end;
$$;

-- ── 5. the guest's own words rank the cards inside a topic (Ahmed, 26 Nov 2026) — = retrieval.ts → normWords / guestWords ──
create or replace function internal.hub_norm(t text) returns text
language sql immutable set search_path = '' as $$
  select btrim(regexp_replace(regexp_replace(translate(lower(coalesce(t, '')), 'أإآةى', 'اااهي'), '[\u064B-\u0652\u0640]', '', 'g'),
                              '[[:punct:]؟،؛«»“”‘’…]+', ' ', 'g'))
$$;
create or replace function internal.hub_stop_words() returns text[]
language sql immutable set search_path = '' as $$
  select array['عندكم', 'عندكو', 'عندكوا', 'عندك', 'عندهم', 'لديكم', 'لديك', 'فيه', 'فيها', 'هل', 'يوجد', 'توجد', 'موجود', 'موجوده', 'متوفر', 'متوفره', 'يتوفر', 'تتوفر', 'غرف', 'غرفه', 'تجهيزات', 'ايش', 'وش', 'شو', 'ماذا', 'كيف', 'ممكن', 'لو', 'سمحت', 'فندق', 'لكم', 'عن', 'على', 'علي', 'من', 'الى', 'الي', 'مع', 'هذا', 'هذه', 'ابغى', 'ابغي', 'ابي', 'اريد', 'نبي', 'نبغى', 'نبغي', 'كم', 'متى', 'وين', 'اين', 'انا', 'احنا', 'نحن', 'السلام', 'عليكم', 'مرحبا', 'اهلا', 'لو', 'يا', 'do', 'does', 'you', 'have', 'the', 'rooms', 'room', 'is', 'are', 'there', 'any', 'what', 'your', 'and', 'for', 'with', 'please', 'hotel', 'can', 'how', 'hello', 'thanks', 'thank', 'would', 'like', 'want', 'need']::text[]
$$;
create or replace function internal.hub_guest_words(t text) returns text[]
language sql immutable set search_path = '' as $$
  select coalesce(array_agg(distinct y.w order by y.w), '{}') from (
    select case when char_length(x) >= 5 and x ~ '^(وال|بال|فال|كال|لل|ال)' then regexp_replace(x, '^(وال|بال|فال|كال|لل|ال)', '') else x end as w
      from regexp_split_to_table(internal.hub_norm(t), '\s+') x) y
   where char_length(y.w) >= 3 and not (y.w = any (internal.hub_stop_words()))
$$;
revoke execute on function internal.hub_norm(text), internal.hub_stop_words(), internal.hub_guest_words(text) from public, anon, authenticated;
drop function if exists public.hub_knowledge_for(text, text[], text, text);
drop function if exists public.hub_knowledge_for_eval(text, text[], text, text, uuid[]);

create function public.hub_knowledge_for(p_unit text, p_topics text[], p_language text, p_branch text default null, p_text text default null) returns jsonb
language plpgsql stable security definer set search_path = '' as $$
declare
  u public.hub_units;
  v_keys text[];
  v_focus text[];
  v_named text[];
  v_hidden text[] := array(select x.key from public.hub_units x where x.knowledge_hidden);
  v_rel text[];
  v_n integer := greatest(internal.hub_setting_int('hub_cards_per_turn', 5), 1);
  v_lang text := case when p_language = 'en' then 'en' else 'ar' end;
  v_today date := internal.riyadh_today();
  v_cards jsonb;
  -- S2e: the guest's own words (a card naming one of them ranks first inside the cap)
  v_words text[] := internal.hub_guest_words(p_text);
  v_faq jsonb;
  -- H9 fix 3: the owner's reply rules for these topics (how to answer — never facts)
  v_rules jsonb;
begin
  select * into u from public.hub_units where key = p_unit;
  if u.id is null then raise exception 'hub_unit' using errcode = '22023'; end if;
  if u.knowledge_hidden or cardinality(coalesce(p_topics, '{}')) = 0 then
    return jsonb_build_object('unit', u.key, 'language', v_lang, 'cards', '[]'::jsonb, 'faq', '[]'::jsonb);
  end if;
  -- the number's own branch: every unit of it (a branch unit with its venues; a dining unit with its branch)
  -- S2d: a unit with no branch («السوشيال») is one of its own units (a card tagged with it ranks first)
  v_keys := array(select x.key from public.hub_units x where x.branch_slug = u.branch_slug or x.id = u.id);
  -- the units of the branch the guest named (empty when none, «both» or this number's own branch)
  v_named := case when p_branch is not null and p_branch <> 'both' and p_branch <> u.branch_slug
                  then array(select x.key from public.hub_units x where x.branch_slug = p_branch) else '{}' end;
  v_focus := case when cardinality(v_named) > 0 then v_named else v_keys end;
  v_rel := array(select t.parent_key from public.hub_topics t where t.key = any (p_topics) and t.parent_key is not null
                 union select t.key from public.hub_topics t where t.parent_key = any (p_topics));
  select coalesce(jsonb_agg(jsonb_build_object('id', z.id, 'key', z.key, 'title', z.live ->> ('title_' || v_lang), 'text', z.live ->> ('text_' || v_lang),
                                               'source', z.live ->> 'source', 'source_date', z.live ->> 'source_date', 'unit_keys', z.live -> 'unit_keys',
                                               'topic_keys', z.live -> 'topic_keys',
                                               'branch', (select x.branch_slug from public.hub_units x where x.key = (z.live -> 'unit_keys' ->> 0))) order by z.word_first, z.rank_unit, z.words desc, z.exact desc, z.related desc, z.sort, z.key), '[]'::jsonb)
    into v_cards from (
      select c.id, c.key, c.live, c.sort,
             case when c.unit_keys <@ v_focus and cardinality(c.unit_keys) > 0 then 0
                  when c.unit_keys && v_focus then 1
                  when cardinality(c.unit_keys) = 0 then 2
                  else 3 end as rank_unit,
             (select count(*) from unnest(c.topic_keys) k where k = any (p_topics)) as exact,
             (select count(*) from unnest(v_words) w where internal.hub_norm(concat_ws(' ', c.live ->> 'title_ar', c.live ->> 'text_ar', c.live ->> 'title_en', c.live ->> 'text_en')) like '%' || w || '%') as words,
             case when (cardinality(c.unit_keys) = 0 or c.unit_keys && v_focus) and exists (select 1 from unnest(v_words) w where internal.hub_norm(concat_ws(' ', c.live ->> 'title_ar', c.live ->> 'text_ar', c.live ->> 'title_en', c.live ->> 'text_en')) like '%' || w || '%') then 0 else 1 end as word_first,
             (select count(*) from unnest(c.topic_keys) k where k = any (v_rel)) as related
        from (select k.id, k.key, k.live, k.sort, array(select jsonb_array_elements_text(k.live -> 'unit_keys')) as unit_keys,
                     array(select jsonb_array_elements_text(k.live -> 'topic_keys')) as topic_keys
                from public.hub_knowledge_cards k
               where k.status = 'published' and k.live is not null and not k.is_test and k.card_kind = 'fact'
                 and ((k.live ->> 'expires_on') is null or (k.live ->> 'expires_on')::date >= v_today)) c
       where not (c.unit_keys && v_hidden)
         and (c.topic_keys && p_topics or c.topic_keys && v_rel)
         -- the café menu and ordering cards: on their own branch's numbers, or when the guest named that branch
         and (not (c.key = any (internal.hub_branch_only_cards())) or c.unit_keys && v_keys or c.unit_keys && v_named)
       order by word_first, rank_unit, words desc, exact desc, related desc, c.sort, c.key
       limit v_n) z;
  select coalesce(jsonb_agg(jsonb_build_object('key', z.key, 'q', z.live ->> ('q_' || v_lang), 'a', internal.hub_fill_fees(z.live ->> ('a_' || v_lang), v_lang))
                            order by z.mine desc, z.hits desc, z.sort, z.key), '[]'::jsonb)
    into v_faq from (
      select y.* from (
        select f.key, f.live, (f.live ->> 'sort')::int as sort,
               coalesce(t.unit_keys && v_focus, false) as mine,
               (select count(*) from unnest(coalesce(t.topic_keys, '{}')) k where k = any (p_topics)) * 2
               + (select count(*) from unnest(coalesce(t.topic_keys, '{}')) k where k = any (v_rel)) as hits
          from public.faq_items f left join public.hub_faq_topics t on t.faq_key = f.key
         where f.live is not null and not coalesce((f.live ->> 'hidden')::boolean, false) and not f.is_test) y
       where y.hits > 0
       order by y.mine desc, y.hits desc, y.sort, y.key
       limit v_n) z;
  select coalesce(jsonb_agg(jsonb_build_object('id', k.id, 'key', k.key, 'title', k.live ->> ('title_' || v_lang), 'text', k.live ->> ('text_' || v_lang), 'card_kind', 'rule')
                            order by k.sort, k.key), '[]'::jsonb)
    into v_rules from (select k.* from public.hub_knowledge_cards k
                        where k.card_kind = 'rule' and k.status = 'published' and k.live is not null and not k.is_test
                          and ((k.live ->> 'expires_on') is null or (k.live ->> 'expires_on')::date >= v_today)
                          and array(select jsonb_array_elements_text(k.live -> 'topic_keys')) && (p_topics || v_rel)
                          and (cardinality(array(select jsonb_array_elements_text(k.live -> 'unit_keys'))) = 0
                               or array(select jsonb_array_elements_text(k.live -> 'unit_keys')) && v_focus)
                        order by k.sort, k.key limit 5) k;
  return jsonb_build_object('unit', u.key, 'language', v_lang, 'branch', coalesce(p_branch, u.branch_slug), 'cards', v_cards, 'faq', v_faq, 'rules', v_rules);
end;
$$;

create function public.hub_knowledge_for_eval(p_unit text, p_topics text[], p_language text, p_branch text default null, p_cards uuid[] default null, p_text text default null) returns jsonb
language plpgsql stable security definer set search_path = '' as $$
declare
  u public.hub_units;
  v_keys text[];
  v_focus text[];
  v_named text[];
  v_hidden text[] := array(select x.key from public.hub_units x where x.knowledge_hidden);
  v_rel text[];
  v_n integer := greatest(internal.hub_setting_int('hub_cards_per_turn', 5), 1);
  v_lang text := case when p_language = 'en' then 'en' else 'ar' end;
  v_today date := internal.riyadh_today();
  v_cards jsonb;
  -- S2e: the guest's own words (a card naming one of them ranks first inside the cap)
  v_words text[] := internal.hub_guest_words(p_text);
  v_faq jsonb;
begin
  select * into u from public.hub_units where key = p_unit;
  if u.id is null then raise exception 'hub_unit' using errcode = '22023'; end if;
  if u.knowledge_hidden or cardinality(coalesce(p_topics, '{}')) = 0 then
    return jsonb_build_object('unit', u.key, 'language', v_lang, 'cards', '[]'::jsonb, 'faq', '[]'::jsonb);
  end if;
  -- the number's own branch: every unit of it (a branch unit with its venues; a dining unit with its branch)
  -- S2d: a unit with no branch («السوشيال») is one of its own units (a card tagged with it ranks first)
  v_keys := array(select x.key from public.hub_units x where x.branch_slug = u.branch_slug or x.id = u.id);
  -- the units of the branch the guest named (empty when none, «both» or this number's own branch)
  v_named := case when p_branch is not null and p_branch <> 'both' and p_branch <> u.branch_slug
                  then array(select x.key from public.hub_units x where x.branch_slug = p_branch) else '{}' end;
  v_focus := case when cardinality(v_named) > 0 then v_named else v_keys end;
  v_rel := array(select t.parent_key from public.hub_topics t where t.key = any (p_topics) and t.parent_key is not null
                 union select t.key from public.hub_topics t where t.parent_key = any (p_topics));
  select coalesce(jsonb_agg(jsonb_build_object('id', z.id, 'key', z.key, 'title', z.live ->> ('title_' || v_lang), 'text', z.live ->> ('text_' || v_lang),
                                               'source', z.live ->> 'source', 'source_date', z.live ->> 'source_date', 'unit_keys', z.live -> 'unit_keys',
                                               'topic_keys', z.live -> 'topic_keys',
                                               'branch', (select x.branch_slug from public.hub_units x where x.key = (z.live -> 'unit_keys' ->> 0))) order by z.word_first, z.rank_unit, z.words desc, z.exact desc, z.related desc, z.sort, z.key), '[]'::jsonb)
    into v_cards from (
      select c.id, c.key, c.live, c.sort,
             case when c.unit_keys <@ v_focus and cardinality(c.unit_keys) > 0 then 0
                  when c.unit_keys && v_focus then 1
                  when cardinality(c.unit_keys) = 0 then 2
                  else 3 end as rank_unit,
             (select count(*) from unnest(c.topic_keys) k where k = any (p_topics)) as exact,
             (select count(*) from unnest(v_words) w where internal.hub_norm(concat_ws(' ', c.live ->> 'title_ar', c.live ->> 'text_ar', c.live ->> 'title_en', c.live ->> 'text_en')) like '%' || w || '%') as words,
             case when (cardinality(c.unit_keys) = 0 or c.unit_keys && v_focus) and exists (select 1 from unnest(v_words) w where internal.hub_norm(concat_ws(' ', c.live ->> 'title_ar', c.live ->> 'text_ar', c.live ->> 'title_en', c.live ->> 'text_en')) like '%' || w || '%') then 0 else 1 end as word_first,
             (select count(*) from unnest(c.topic_keys) k where k = any (v_rel)) as related
        from (select k.id, k.key, k.live, k.sort, array(select jsonb_array_elements_text(k.live -> 'unit_keys')) as unit_keys,
                     array(select jsonb_array_elements_text(k.live -> 'topic_keys')) as topic_keys
                from (select x.id, x.key, x.sort, x.status,
                             case when x.id = any (coalesce(p_cards, '{}')) then false else x.is_test end as is_test,
                             case when x.id = any (coalesce(p_cards, '{}')) then internal.hub_card_snapshot(x) else x.live end as live
                        from public.hub_knowledge_cards x
                       where ((x.id = any (coalesce(p_cards, '{}')) and x.status <> 'archived') or (x.status = 'published' and x.live is not null)) and x.card_kind = 'fact') k
               where k.live is not null and not k.is_test
                 and ((k.live ->> 'expires_on') is null or (k.live ->> 'expires_on')::date >= v_today)) c
       where not (c.unit_keys && v_hidden)
         and (c.topic_keys && p_topics or c.topic_keys && v_rel)
         -- the café menu and ordering cards: on their own branch's numbers, or when the guest named that branch
         and (not (c.key = any (internal.hub_branch_only_cards())) or c.unit_keys && v_keys or c.unit_keys && v_named)
       order by word_first, rank_unit, words desc, exact desc, related desc, c.sort, c.key
       limit v_n) z;
  select coalesce(jsonb_agg(jsonb_build_object('key', z.key, 'q', z.live ->> ('q_' || v_lang), 'a', internal.hub_fill_fees(z.live ->> ('a_' || v_lang), v_lang))
                            order by z.mine desc, z.hits desc, z.sort, z.key), '[]'::jsonb)
    into v_faq from (
      select y.* from (
        select f.key, f.live, (f.live ->> 'sort')::int as sort,
               coalesce(t.unit_keys && v_focus, false) as mine,
               (select count(*) from unnest(coalesce(t.topic_keys, '{}')) k where k = any (p_topics)) * 2
               + (select count(*) from unnest(coalesce(t.topic_keys, '{}')) k where k = any (v_rel)) as hits
          from public.faq_items f left join public.hub_faq_topics t on t.faq_key = f.key
         where f.live is not null and not coalesce((f.live ->> 'hidden')::boolean, false) and not f.is_test) y
       where y.hits > 0
       order by y.mine desc, y.hits desc, y.sort, y.key
       limit v_n) z;
  return jsonb_build_object('unit', u.key, 'language', v_lang, 'branch', coalesce(p_branch, u.branch_slug), 'cards', v_cards, 'faq', v_faq);
end;
$$;

revoke execute on function public.hub_knowledge_for(text, text[], text, text, text), public.hub_knowledge_for_eval(text, text[], text, text, uuid[], text) from public, anon, authenticated;
grant execute on function public.hub_knowledge_for(text, text[], text, text, text), public.hub_knowledge_for_eval(text, text[], text, text, uuid[], text) to service_role;

-- ── 6. the lab: the thread cases and the amenities card on the branch numbers ──
update public.hub_test_items
   set context = $s2e${"kind":"instagram","parent":"user"}$s2e$::jsonb, expect = $s2e${"action":"comment","public":false,"private":false,"handoff":false}$s2e$::jsonb, note = $s2e$a reply in a thread between users (an argument): the classifier sees IN_THREAD and nothing is posted (SOCIAL-SPEC §5.4)$s2e$
 where key = 'c2-11';
do $$
declare v_sort integer := coalesce((select max(sort) from public.hub_test_items), 0) + 1;
begin
  insert into public.hub_test_items (key, unit_key, language, messages, context, expect, note, tags, added_from, sort)
  select e ->> 'key', e ->> 'unit', e ->> 'language', e -> 'messages', coalesce(e -> 'context', '{}'::jsonb), e -> 'expect', e ->> 'note',
         array(select jsonb_array_elements_text(e -> 'tags')), 'seed', v_sort + (o - 1)::integer
